8981: void __init sched_init(void)
8982: {
8983: 	unsigned long ptr = 0;
8984: 	int i;
8985: 
8986: 	/* Make sure the linker didn't screw up */
8987: 	BUG_ON(&idle_sched_class + 1 != &fair_sched_class ||
8988: 	       &fair_sched_class + 1 != &rt_sched_class ||
8989: 	       &rt_sched_class + 1   != &dl_sched_class);
8990: #ifdef CONFIG_SMP
8991: 	BUG_ON(&dl_sched_class + 1 != &stop_sched_class);
8992: #endif
8993: 
8994: 	wait_bit_init();
8995: 
8996: #ifdef CONFIG_FAIR_GROUP_SCHED
8997: 	ptr += 2 * nr_cpu_ids * sizeof(void **);
8998: #endif
8999: #ifdef CONFIG_RT_GROUP_SCHED
9000: 	ptr += 2 * nr_cpu_ids * sizeof(void **);
9001: #endif
9002: 	if (ptr) {
9003: 		ptr = (unsigned long)kzalloc(ptr, GFP_NOWAIT);
9004: 
9005: #ifdef CONFIG_FAIR_GROUP_SCHED
9006: 		root_task_group.se = (struct sched_entity **)ptr;
9007: 		ptr += nr_cpu_ids * sizeof(void **);
9008: 
9009: 		root_task_group.cfs_rq = (struct cfs_rq **)ptr;
9010: 		ptr += nr_cpu_ids * sizeof(void **);
9011: 
9012: 		root_task_group.shares = ROOT_TASK_GROUP_LOAD;
9013: 		init_cfs_bandwidth(&root_task_group.cfs_bandwidth);
9014: #endif /* CONFIG_FAIR_GROUP_SCHED */
9015: #ifdef CONFIG_RT_GROUP_SCHED
9016: 		root_task_group.rt_se = (struct sched_rt_entity **)ptr;
9017: 		ptr += nr_cpu_ids * sizeof(void **);
9018: 
9019: 		root_task_group.rt_rq = (struct rt_rq **)ptr;
9020: 		ptr += nr_cpu_ids * sizeof(void **);
9021: 
9022: #endif /* CONFIG_RT_GROUP_SCHED */
9023: 	}
9024: #ifdef CONFIG_CPUMASK_OFFSTACK
9025: 	for_each_possible_cpu(i) {
9026: 		per_cpu(load_balance_mask, i) = (cpumask_var_t)kzalloc_node(
9027: 			cpumask_size(), GFP_KERNEL, cpu_to_node(i));
9028: 		per_cpu(select_idle_mask, i) = (cpumask_var_t)kzalloc_node(
9029: 			cpumask_size(), GFP_KERNEL, cpu_to_node(i));
9030: 	}
9031: #endif /* CONFIG_CPUMASK_OFFSTACK */
9032: 
9033: 	init_rt_bandwidth(&def_rt_bandwidth, global_rt_period(), global_rt_runtime());
9034: 	init_dl_bandwidth(&def_dl_bandwidth, global_rt_period(), global_rt_runtime());
9035: 
9036: #ifdef CONFIG_SMP
9037: 	init_defrootdomain();
9038: #endif
9039: 
9040: #ifdef CONFIG_RT_GROUP_SCHED
9041: 	init_rt_bandwidth(&root_task_group.rt_bandwidth,
9042: 			global_rt_period(), global_rt_runtime());
9043: #endif /* CONFIG_RT_GROUP_SCHED */
9044: 
9045: #ifdef CONFIG_CGROUP_SCHED
9046: 	task_group_cache = KMEM_CACHE(task_group, 0);
9047: 
9048: 	list_add(&root_task_group.list, &task_groups);
9049: 	INIT_LIST_HEAD(&root_task_group.children);
9050: 	INIT_LIST_HEAD(&root_task_group.siblings);
9051: 	autogroup_init(&init_task);
9052: #endif /* CONFIG_CGROUP_SCHED */
9053: 
9054: 	for_each_possible_cpu(i) {
9055: 		struct rq *rq;
9056: 
9057: 		rq = cpu_rq(i);
9058: 		raw_spin_lock_init(&rq->__lock);
9059: 		rq->nr_running = 0;
9060: 		rq->calc_load_active = 0;
9061: 		rq->calc_load_update = jiffies + LOAD_FREQ;
9062: 		init_cfs_rq(&rq->cfs);
9063: 		init_rt_rq(&rq->rt);
9064: 		init_dl_rq(&rq->dl);
9065: #ifdef CONFIG_FAIR_GROUP_SCHED
9066: 		INIT_LIST_HEAD(&rq->leaf_cfs_rq_list);
9067: 		rq->tmp_alone_branch = &rq->leaf_cfs_rq_list;
9068: 		/*
9069: 		 * How much CPU bandwidth does root_task_group get?
9070: 		 *
9071: 		 * In case of task-groups formed thr' the cgroup filesystem, it
9072: 		 * gets 100% of the CPU resources in the system. This overall
9073: 		 * system CPU resource is divided among the tasks of
9074: 		 * root_task_group and its child task-groups in a fair manner,
9075: 		 * based on each entity's (task or task-group's) weight
9076: 		 * (se->load.weight).
9077: 		 *
9078: 		 * In other words, if root_task_group has 10 tasks of weight
9079: 		 * 1024) and two child groups A0 and A1 (of weight 1024 each),
9080: 		 * then A0's share of the CPU resource is:
9081: 		 *
9082: 		 *	A0's bandwidth = 1024 / (10*1024 + 1024 + 1024) = 8.33%
9083: 		 *
9084: 		 * We achieve this by letting root_task_group's tasks sit
9085: 		 * directly in rq->cfs (i.e root_task_group->se[] = NULL).
9086: 		 */
9087: 		init_tg_cfs_entry(&root_task_group, &rq->cfs, NULL, i, NULL);
9088: #endif /* CONFIG_FAIR_GROUP_SCHED */
9089: 
9090: 		rq->rt.rt_runtime = def_rt_bandwidth.rt_runtime;
9091: #ifdef CONFIG_RT_GROUP_SCHED
9092: 		init_tg_rt_entry(&root_task_group, &rq->rt, NULL, i, NULL);
9093: #endif
9094: #ifdef CONFIG_SMP
9095: 		rq->sd = NULL;
9096: 		rq->rd = NULL;
9097: 		rq->cpu_capacity = rq->cpu_capacity_orig = SCHED_CAPACITY_SCALE;
9098: 		rq->balance_callback = &balance_push_callback;
9099: 		rq->active_balance = 0;
9100: 		rq->next_balance = jiffies;
9101: 		rq->push_cpu = 0;
9102: 		rq->cpu = i;
9103: 		rq->online = 0;
9104: 		rq->idle_stamp = 0;
9105: 		rq->avg_idle = 2*sysctl_sched_migration_cost;
9106: 		rq->wake_stamp = jiffies;
9107: 		rq->wake_avg_idle = rq->avg_idle;
9108: 		rq->max_idle_balance_cost = sysctl_sched_migration_cost;
9109: 
9110: 		INIT_LIST_HEAD(&rq->cfs_tasks);
9111: 
9112: 		rq_attach_root(rq, &def_root_domain);
9113: #ifdef CONFIG_NO_HZ_COMMON
9114: 		rq->last_blocked_load_update_tick = jiffies;
9115: 		atomic_set(&rq->nohz_flags, 0);
9116: 
9117: 		INIT_CSD(&rq->nohz_csd, nohz_csd_func, rq);
9118: #endif
9119: #ifdef CONFIG_HOTPLUG_CPU
9120: 		rcuwait_init(&rq->hotplug_wait);
9121: #endif
9122: #endif /* CONFIG_SMP */
9123: 		hrtick_rq_init(rq);
9124: 		atomic_set(&rq->nr_iowait, 0);
9125: 
9126: #ifdef CONFIG_SCHED_CORE
9127: 		rq->core = rq;
9128: 		rq->core_pick = NULL;
9129: 		rq->core_enabled = 0;
9130: 		rq->core_tree = RB_ROOT;
9131: 		rq->core_forceidle = false;
9132: 
9133: 		rq->core_cookie = 0UL;
9134: #endif
9135: 	}

574: void set_cpu_sibling_map(int cpu)
575: {
576: 	bool has_smt = smp_num_siblings > 1;
577: 	bool has_mp = has_smt || boot_cpu_data.x86_max_cores > 1;
578: 	struct cpuinfo_x86 *c = &cpu_data(cpu);
579: 	struct cpuinfo_x86 *o;
580: 	int i, threads;
581: 
582: 	cpumask_set_cpu(cpu, cpu_sibling_setup_mask);
583: 
584: 	if (!has_mp) {
585: 		cpumask_set_cpu(cpu, topology_sibling_cpumask(cpu));
586: 		cpumask_set_cpu(cpu, cpu_llc_shared_mask(cpu));
587: 		cpumask_set_cpu(cpu, topology_core_cpumask(cpu));
588: 		cpumask_set_cpu(cpu, topology_die_cpumask(cpu));
589: 		c->booted_cores = 1;
590: 		return;
591: 	}
592: 
593: 	for_each_cpu(i, cpu_sibling_setup_mask) {
594: 		o = &cpu_data(i);
595: 
596: 		if (match_pkg(c, o) && !topology_same_node(c, o))
597: 			x86_has_numa_in_package = true;
598: 
599: 		if ((i == cpu) || (has_smt && match_smt(c, o)))
600: 			link_mask(topology_sibling_cpumask, cpu, i);
601: 
602: 		if ((i == cpu) || (has_mp && match_llc(c, o)))
603: 			link_mask(cpu_llc_shared_mask, cpu, i);
604: 
605: 		if ((i == cpu) || (has_mp && match_die(c, o)))
606: 			link_mask(topology_die_cpumask, cpu, i);
607: 	}
608: 
609: 	threads = cpumask_weight(topology_sibling_cpumask(cpu));
610: 	if (threads > __max_smt_threads)
611: 		__max_smt_threads = threads;
612: 
613: 	/*
614: 	 * This needs a separate iteration over the cpus because we rely on all
615: 	 * topology_sibling_cpumask links to be set-up.
616: 	 */
617: 	for_each_cpu(i, cpu_sibling_setup_mask) {
618: 		o = &cpu_data(i);
619: 
620: 		if ((i == cpu) || (has_mp && match_pkg(c, o))) {
621: 			link_mask(topology_core_cpumask, cpu, i);
622: 
623: 			/*
624: 			 *  Does this new cpu bringup a new core?
625: 			 */
626: 			if (threads == 1) {
627: 				/*
628: 				 * for each core in package, increment
629: 				 * the booted_cores for this new cpu
630: 				 */
631: 				if (cpumask_first(
632: 				    topology_sibling_cpumask(i)) == i)
633: 					c->booted_cores++;
634: 				/*
635: 				 * increment the core count for all
636: 				 * the other cpus in this package
637: 				 */
638: 				if (i != cpu)
639: 					cpu_data(i).booted_cores++;
640: 			} else if (i != cpu && !c->booted_cores)
641: 				c->booted_cores = cpu_data(i).booted_cores;
642: 		}
643: 	}
644: }

